class CosmosQuery
{
    // BREAKING CHANGE 4 — Synchronous I/O removed.
    // The Cosmos provider in EF Core 9 no longer supports sync APIs
    // (.ToList(), .First(), .SaveChanges(), etc.).
    // All calls must be async.
    async Task FindProducts(ProductContext ctx)
    {
        // Raw SQL still works — references c.Discriminator which we preserved above.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products
            .Where(p => p.Sku == "ABC")
            .ToListAsync();
    }
}

