 using Microsoft.EntityFrameworkCore;
 using Microsoft.EntityFrameworkCore.ChangeTracking;
 using Microsoft.EntityFrameworkCore.ValueGeneration;
 class ProductContext : DbContext
 {
     public DbSet<Product> Products => Set<Product>();
     protected override void OnModelCreating(ModelBuilder modelBuilder)
     {
         modelBuilder.Entity<Product>(b =>
         {
             b.ToContainer("Products");

             // BREAKING CHANGE 1 — Discriminator property renamed.
             // EF Core 9 writes "$type" by default instead of "Discriminator".
             // Existing 500K documents use "Discriminator", and our raw SQL
             // queries (c.Discriminator = 'Product') depend on it.
             // Opt back into the old property name to keep data compatible.
             b.HasDiscriminator<string>("Discriminator");

             // BREAKING CHANGE 2 — id format changed.
             // EF Core 8 generated id as "Product|123"; EF Core 9 uses just "123".
             // Existing documents still have the prefixed format.  We define a
             // read/write shadow property mapped to the JSON "id" field so the
             // provider never auto-generates a new-format value.  A value
             // generator keeps new inserts consistent with the old format.
             b.Property<string>("__id")
                 .ToJsonProperty("id")
                 .HasValueGenerator<ProductIdGenerator>();

             // BREAKING CHANGE 3 — HasIndex now throws at model build time.
             // The Cosmos provider never supported indexes through EF Core
             // (they are managed in the Azure portal / Cosmos SDK).
             // EF Core 8 silently ignored the call; EF Core 9 throws.
             // ➜ Removed the HasIndex call. Manage indexes via Cosmos directly.
         });
     }
 }

 class Product
 {
     public int Id { get; set; }
     public string Sku { get; set; } = null!;
 }

 // Preserves the EF Core 8 id format ("Product|{key}") for new documents
 // so they are consistent with the 500K existing documents.

 class ProductIdGenerator : ValueGenerator<string>
 {
     public override bool GeneratesTemporaryValues => false;

     public override string Next(EntityEntry entry)
     {
         var pk = entry.Property("Id").CurrentValue;
         return $"Product|{pk}";
     }
 }

